2e6537}.ads-feedback[data-correct=false] .ads-verdict{background:#f5dfda;color:#8b352e}.ads-line{margin:0;color:#534b42;font-size:.7rem;font-weight:760;line-height:1.42}.ads-line strong{color:#2c3940}.ads-line:last-of-type{padding-top:.25rem;border-top:1px solid #d7ccbb;color:#675f58;font-size:.64rem;line-height:1.35}.ads-next{min-height:3rem;border:1px solid #294a58;border-radius:.76rem;background:linear-gradient(155deg,#527484,#304f5d);color:#fff;font-size:.82rem;font-weight:1000;letter-spacing:.04em;cursor:pointer;touch-action:manipulation;box-shadow:inset 0 1px rgba(255,255,255,.35),0 4px 9px rgba(29,51,61,.2)}.ads-next:disabled{opacity:.5}.ads-hint{margin:0;color:#756d65;text-align:center;font-size:.66rem;font-weight:750;line-height:1.35}.ads-stage[data-phase=review] .ads-status{border-color:#c6b690;background:#fff7df}.ads-stage[data-phase=final] .ads-status{border-color:#b9944c;background:#fff3c7;color:#624b1e}.ads-stage[data-phase=timeout] .ads-status{border-color:#bd8f6f;background:#f6e4d9;color:#783d2c}.ads-stage[data-reduced=true] .ads-answer,.ads-stage[data-reduced=true] .ads-next{transition:none!important}
