import game from "../src/games/attention-driving-safety-v1.js";
import {createGameRuntime} from "../src/game-kernel.js";
const FIXED_TASK=game.generate({randomInt:min=>min}),host=document.querySelector("#game-host"),label=document.querySelector("#fixture-label"),prompt=document.querySelector("#prompt"),help=document.querySelector("#help"),resultNode=document.querySelector("#fixture-result"),errors=[];
let runtime=null,qa=null,result=null,lastTask=null;
addEventListener("error",event=>errors.push(String(event.error?.stack||event.message)));addEventListener("unhandledrejection",event=>errors.push(String(event.reason?.stack||event.reason)));
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
function start({task=FIXED_TASK,width=innerWidth,height=innerHeight,dpr=devicePixelRatio,reduced=false,deadlineOverride=null}={}){
  runtime?.dispose();host.replaceChildren();qa={};result=null;resultNode.textContent="";lastTask=structuredClone(task);prompt.textContent=lastTask.prompt;help.textContent=lastTask.help;
  runtime=createGameRuntime({host,qa,reducedMotion:reduced,viewport:{width,height,dpr},onFinish:(correct,detail)=>{result={correct,detail};resultNode.textContent=`${correct?"全問正解":"確認終了"} · ${detail.detail||detail.reason||""}`}});
  const context={...runtime.context,qa,reducedMotion:reduced,viewport:{width,height,dpr}};if(deadlineOverride!==null){const owned=context.setDeadline;context.setDeadline=(_ms,fn)=>owned(deadlineOverride,fn)}game.render(lastTask,context);label.textContent=`${width}×${height} DPR${dpr}${reduced?" reduced":""}`;return structuredClone(lastTask);
}
const api=()=>qa?.[game.metadata.id],settle=()=>api()?.completeTransition?.(),questionIndex=id=>lastTask.questions.findIndex(question=>question.id===id);
const review=id=>{const index=questionIndex(id);api().showScene(index,"question");api().answer(lastTask.questions[index].answer);settle()};
const finishWith=choices=>{for(let index=0;index<lastTask.questions.length;index++){api().answer(choices[index]);settle();api().next()}};
async function scenario(name,reduced){
  if(name==="selected")api().preview(true);
  else if(name==="crosswalk-feedback")review("crosswalk");
  else if(name==="phone")api().showScene(questionIndex("phone"),"question");
  else if(name==="phone-feedback")review("phone");
  else if(name==="railway")api().showScene(questionIndex("railway"),"question");
  else if(name==="railway-feedback")review("railway");
  else if(name==="alcohol")api().showScene(questionIndex("alcohol"),"question");
  else if(name==="alcohol-feedback")review("alcohol");
  else if(name==="fatigue")api().showScene(questionIndex("fatigue"),"question");
  else if(name==="fatigue-feedback"||name==="reduced-feedback")review("fatigue");
  else if(name==="success")finishWith(lastTask.proof.answers);
  else if(name==="mixed")finishWith(lastTask.proof.answers.map((answer,index)=>index===1||index===3?!answer:answer));
  else if(name==="all-wrong")finishWith(lastTask.proof.answers.map(answer=>!answer));
  else if(name==="touch"){const button=host.querySelector?.('.ads-answer[data-value="true"]')||host.children[1].children[4].children[0];button.dispatchEvent(new PointerEvent("pointerdown",{pointerType:"touch",bubbles:true,cancelable:true}));button.dispatchEvent(new MouseEvent("click",{bubbles:true,cancelable:true,detail:1}))}
  else if(name==="keyboard"){host.children[1].dispatchEvent(new KeyboardEvent("keydown",{key:"O",bubbles:true,cancelable:true}))}
  else if(name==="focus"){const stage=host.children[1],controls=stage.children[4];controls.children[1].focus()}
  if(reduced)await wait(235);else if(name==="selected")await wait(80);else if(name==="touch"||name==="keyboard")await wait(460);else await wait(40);document.documentElement.dataset.ready="true";document.body.dataset.scenario=name;
}
window.drivingSafetyFixture={game,start,scenario:name=>scenario(name,false),dispose(){runtime?.dispose()},inspect(){return api()?.inspect?.()||null},preview(value){return api()?.preview?.(value)},answer(value){return api()?.answer?.(value)},next(){return api()?.next?.()},complete(){return settle()},show(id,phase="question"){return api()?.showScene?.(questionIndex(id),phase)},timeout(){return api()?.timeout?.()},runtime(){return runtime?.inspect()||null},task(){return structuredClone(lastTask)},result(){return result?structuredClone(result):null},errors(){return[...errors]},evidence(){const width=innerWidth,resources=performance.getEntriesByType("resource").map(entry=>entry.name),external=resources.filter(name=>new URL(name,location.href).origin!==location.origin);return{scenario:document.body.dataset.scenario||"",viewport:{width,height:innerHeight,dpr:devicePixelRatio,scrollWidth:document.body.scrollWidth},task:structuredClone(lastTask),game:api()?.inspect?.()||null,result:result?structuredClone(result):null,runtime:runtime?.inspect?.()||null,errors:[...errors],resources,external,overflow:document.body.scrollWidth>width}}};
const query=new URLSearchParams(location.search),name=query.get("scenario")||"initial",reduced=query.get("reduced")==="1"||name==="reduced-feedback",deadline=name==="timeout"?120:null;start({width:innerWidth,height:innerHeight,dpr:devicePixelRatio,reduced,deadlineOverride:deadline});if(name==="timeout"){api().answer(lastTask.questions[0].answer);settle();api().next();await wait(180);document.documentElement.dataset.ready="true";document.body.dataset.scenario=name}else await scenario(name,reduced);

